AxClientAsyncWaiter::AxClientAsyncWaiter(
    AxClient* proxy) : proxy_(proxy) {}

AxClientAsyncWaiter::~AxClientAsyncWaiter() = default;


void AxClientAsyncWaiter::Initialize(
    uint32_t hwnd, uint32_t* out_result) {
  base::RunLoop loop;
  proxy_->Initialize(
      std::move(hwnd),
      base::BindOnce(
          [](base::RunLoop* loop,
             uint32_t* out_result
,
             uint32_t result) {*out_result = std::move(result);
            loop->Quit();
          },
          &loop,
          out_result));
  loop.Run();
}

uint32_t AxClientAsyncWaiter::Initialize(
    uint32_t hwnd) {
  uint32_t async_wait_result;
  Initialize(std::move(hwnd),&async_wait_result);
  return async_wait_result;
}

void AxClientAsyncWaiter::FindAll(
    uint32_t* out_result) {
  base::RunLoop loop;
  proxy_->FindAll(
      base::BindOnce(
          [](base::RunLoop* loop,
             uint32_t* out_result
,
             uint32_t result) {*out_result = std::move(result);
            loop->Quit();
          },
          &loop,
          out_result));
  loop.Run();
}

uint32_t AxClientAsyncWaiter::FindAll(
    ) {
  uint32_t async_wait_result;
  FindAll(&async_wait_result);
  return async_wait_result;
}

void AxClientAsyncWaiter::Shutdown(
    ) {
  base::RunLoop loop;
  proxy_->Shutdown(
      base::BindOnce(
          [](base::RunLoop* loop) {
            loop->Quit();
          },
          &loop));
  loop.Run();
}








